{
  "aggregate": {{ this.params.collection }},
  "pipeline": {{
    (() => {
      const targetDomain = this.params.domain || "";
      const limitCount = Number(this.params.questionLimit) || 10;
      const onlyWrong = this.params.onlyWrong === true || this.params.onlyWrong === "true";
      const excludeIds = this.params.excludeIds || [];
      const targetOrigins = this.params.origins || []; // NEU: Array mit Origin-Werten	
      let matchConditions = {};
      // 1. Einzelner Domain-Filter
      if (typeof targetDomain === "string" && targetDomain.trim() !== "") {
        matchConditions["domain"] = targetDomain;
      }
      // 2. Zusätzlicher Filter für countWrong > 0, falls true
      if (onlyWrong) {
        matchConditions["countWrong"] = { "$exists": true, "$gt": 0 };
      }
      // 3. Bereits geladene Fragen ausschließen ($nin)
      if (Array.isArray(excludeIds) && excludeIds.length > 0) {
        matchConditions["_id"] = { 
          "$nin": excludeIds 
        };
      }
      // 4. NEU: Filtern nach mehreren Origin-Werten aus einem Array
      if (Array.isArray(targetOrigins) && targetOrigins.length > 0) {
        matchConditions["origin"] = {
          "$in": targetOrigins
        };
      }
      let pipeline = [
        {
          "$match": matchConditions
        },
        { 
          "$sample": { "size": limitCount } 
        }
      ];
      pipeline.push(
        {
          "$lookup": {
            "from": "master_answer",
            "localField": "_id",
            "foreignField": "question_id",
            "as": "answers"
          }
        }
      );
      return pipeline;
    })()
  }},
  "cursor": {
    "batchSize": {{ Number(this.params.questionLimit) || 10 }}
  }
}
